def augment(data):
    data['sources'].update({
      'delhiv3':{'label':'Delhi Tourism · city sights','url':'https://www.delhitourism.gov.in/dt/explore-the-city.html'},
      'lucknowv3':{'label':'Lucknow · official tourism overview','url':'https://www.incredibleindia.gov.in/en/uttar-pradesh/lucknow'},
      'srinagarv3':{'label':'Srinagar district · places of interest','url':'https://srinagar.nic.in/places-of-interest/'},
      'fx':{'label':'USD/INR reference · 16 Oct 2026','url':'https://ycharts.com/indicators/us_dollar_to_indian_rupee_exchange_rate'}})
    by={d['id']:d for d in data['destinations']}
    for line in RAW.splitlines():
        ident,name,lat,lon,parent,hours,wiki,acts,notes=line.split('|');num=int(ident);h=float(hours)
        base=by.get(parent);poi=bool(base)
        source='delhiv3' if parent=='059' else 'lucknowv3' if parent=='057' else 'srinagarv3' if parent=='021' else base['source'] if base else 'incredible'
        hub=base['hub'] if base else parent
        d=dict(id=ident,num=num,name=name,lat=float(lat),lon=float(lon),hub=hub,access=base['access'] if base else .75,visitHours=h,days=max(.5,h/8),region=base['region'] if base else 'More Indian cities',source=source,description=notes,activities=acts.split('; '),tags=['City sights','Architecture'] if poi else ['Cities','Culture'],fit='B',climate=base['climate'] if base else 'hill' if num==258 else 'plains',permit=base['permit'] if base else 'general',closedMonths=[],decCaution=base['decCaution'] if base else False,seasonNote='City visit; verify opening and access arrangements.',links=[source],country='India',photoTitles=[wiki],parent=parent if poi else None)
        data['destinations'].append(d);by[ident]=d
        data['nodes'].append(dict(id=ident,name=name,lat=d['lat'],lon=d['lon'],hub=False))
        # Local allowances are editorial, not a promise of a particular service.
        localhours=.4 if poi else (3.5 if num in [259,260] else .75)
        data['edges'].append(dict(id='v3-'+ident,a=parent,b=ident,mode='road',hours=localhours,low=80 if poi else 200,high=350 if poi else 900,source=source,note='Editorial local / regional transfer allowance. Hotel and sightseeing transfers are excluded. Local sights may overlap the city overview’s suggested visit days.',basis='person',months=list(range(1,13)),evidence='Editorial local allowance',access=True))
    # Short explicit local links keep successive sights within their city.
    for parent in sorted({d.get('parent') for d in data['destinations'] if d.get('parent')}):
        sights=[d for d in data['destinations'] if d.get('parent')==parent]
        for a,b in combinations(sights,2):
            data['edges'].append(dict(id=f"local-{a['id']}-{b['id']}",a=a['id'],b=b['id'],mode='road',hours=.4,low=80,high=350,source=a['source'],note='Editorial intra-city planning allowance; traffic and actual public transit can differ. Does not route through an airport.',basis='person',months=list(range(1,13)),evidence='Editorial local allowance',access=True))
    by['059']['name']='Delhi · city overview';by['021']['name']='Srinagar · city and lakes overview'
    data['fx']={'inrPerUsd':94.96,'date':'2026-10-16','source':'fx'}
    data['version']=3
    return data
